import { getTranslations } from "next-intl/server";
import { Download, ExternalLink, HeartHandshake } from "lucide-react";
import PageHero from "@/components/ui/PageHero";
import { badge, buttonSecondary, card } from "@/components/ui/styles";
import credits from "@/content/credits.json";
import { Link } from "@/i18n/navigation";
import type { Locale } from "@/i18n/routing";
import { sourceUrl } from "@/lib/source-url";

// Generated by `npm run licenses` (scripts/licenses/generate.mjs).
type Where = "browser" | "server";
type Embedded = (typeof credits.embedded)[number] & { exactSource?: boolean };
const embedded = credits.embedded as Embedded[];

const linkClass = "inline-flex items-center gap-1 font-medium text-brand underline-offset-2 hover:text-brand-strong hover:underline";

function ExtLink({ href, children }: { href: string; children: React.ReactNode }) {
  const external = href.startsWith("http");
  return (
    <a href={href} className={linkClass} {...(external ? { rel: "noopener noreferrer", target: "_blank" } : {})}>
      {children}
      {external && <ExternalLink aria-hidden="true" className="h-3.5 w-3.5 shrink-0" />}
    </a>
  );
}

export default async function CreditsPage({ locale }: { locale: Locale }) {
  const t = await getTranslations({ locale, namespace: "Credits" });
  const whereLabel = (where: string[]) => where.map((w) => t(w as Where)).join(" · ");
  const lgpl = embedded.filter((e) => e.lgpl);
  const engines = embedded.filter((e) => !e.lgpl && e.kind !== "service");
  const services = embedded.filter((e) => e.kind === "service");
  const source = sourceUrl();

  return (
    <article className="mx-auto flex max-w-5xl flex-col gap-12 px-4 py-12">
      <PageHero icon={<HeartHandshake aria-hidden="true" className="h-7 w-7" />} title={t("title")}>
        <p className="max-w-2xl text-lg text-muted text-pretty">{t("intro")}</p>
        <a href="/third-party-notices.txt" download className={buttonSecondary}>
          <Download aria-hidden="true" className="h-4 w-4" />
          {t("download")}
        </a>
        <p className="max-w-xl text-sm text-muted">{t("downloadHint")}</p>
      </PageHero>

      {source && (
        <section aria-labelledby="credits-source" className="flex flex-col gap-4">
          <h2 id="credits-source" className="text-2xl font-bold">
            {t("sourceCodeHeading")}
          </h2>
          <p className="max-w-prose text-muted">{t("sourceCodeIntro")}</p>
          <p>
            <ExtLink href={source}>{t("sourceCodeLink")}</ExtLink>
          </p>
        </section>
      )}

      <section aria-labelledby="credits-lgpl" className="flex flex-col gap-4">
        <h2 id="credits-lgpl" className="text-2xl font-bold">
          {t("lgplHeading")}
        </h2>
        <p className="max-w-prose text-muted">{t("lgplIntro")}</p>
        <p className="max-w-prose text-muted">{t("lameThanks")}</p>
        <ul className="grid gap-4 md:grid-cols-2">
          {lgpl.map((e) => (
            <li key={e.id} className={`flex flex-col gap-3 p-5 ${card}`}>
              <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
                <h3 className="text-lg font-bold break-words">
                  {e.name} <span className="font-sans text-base font-medium text-muted">{e.version}</span>
                </h3>
                <span className={badge}>{e.license}</span>
              </div>
              <p className="text-sm text-muted">
                {e.partOf ? `${t("includedIn", { package: e.partOf })} · ` : ""}
                {whereLabel(e.where)}
              </p>
              {e.exactSource === false && (
                <p className="text-sm text-muted">{t("sourceNotExact", { version: e.version })}</p>
              )}
              <ul className="flex flex-col gap-1.5 text-sm">
                <li>
                  <ExtLink href={e.homepage}>{t("project")}</ExtLink>
                </li>
                {e.source && (
                  <li>
                    <ExtLink href={e.source}>{e.exactSource === false ? t("sourceRepo") : t("source")}</ExtLink>
                  </li>
                )}
                {e.build && (
                  <li>
                    <ExtLink href={e.build}>{t("build")}</ExtLink>
                  </li>
                )}
                <li>
                  <ExtLink href={`/licenses/${e.licenseText}.txt`}>{t("licenseText")}</ExtLink>
                </li>
              </ul>
            </li>
          ))}
        </ul>
      </section>

      <ComponentList id="credits-engines" title={t("enginesHeading")} intro={t("enginesIntro")} items={engines} t={t} whereLabel={whereLabel} />
      <ComponentList id="credits-services" title={t("servicesHeading")} intro={t("servicesIntro")} items={services} t={t} whereLabel={whereLabel} />

      <section aria-labelledby="credits-packages" className="flex flex-col gap-4">
        <h2 id="credits-packages" className="text-2xl font-bold">
          {t("packagesHeading", { count: credits.packages.length })}
        </h2>
        <p className="max-w-prose text-muted">{t("packagesIntro")}</p>
        <div className={`min-w-0 overflow-hidden ${card}`}>
          <div className="max-h-[40rem] overflow-auto" tabIndex={0} role="region" aria-label={t("tableLabel")}>
            {/* 250 rows: cell styles live on the table to keep the page light. */}
            <table className="w-full text-left text-sm [&_a]:font-medium [&_a]:break-all [&_a]:text-brand [&_a:hover]:underline [&_td]:px-4 [&_td]:py-2.5 [&_td:nth-child(n+2)]:text-muted [&_td:nth-child(2)]:tabular-nums [&_td:nth-child(3)]:text-foreground [&_td:not(:nth-child(4))]:whitespace-nowrap [&_th]:px-4 [&_th]:py-3">
              <thead className="sticky top-0 bg-surface-2 text-xs font-semibold text-muted">
                <tr>
                  <th scope="col">{t("name")}</th>
                  <th scope="col">{t("version")}</th>
                  <th scope="col">{t("license")}</th>
                  <th scope="col">{t("author")}</th>
                  <th scope="col">{t("where")}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {credits.packages.map((p) => (
                  <tr key={`${p.name}@${p.version}`}>
                    <td>
                      <a href={p.url} rel="noopener noreferrer">
                        {p.name}
                      </a>
                    </td>
                    <td>{p.version}</td>
                    <td>{p.license}</td>
                    <td>{"author" in p && p.author ? p.author : "—"}</td>
                    <td>{whereLabel(p.where)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </section>

      <p className="text-muted">
        <Link href="/contact" className={linkClass}>
          {t("questions")}
        </Link>
      </p>
    </article>
  );
}

function ComponentList({
  id,
  title,
  intro,
  items,
  t,
  whereLabel,
}: {
  id: string;
  title: string;
  intro: string;
  items: Embedded[];
  t: Awaited<ReturnType<typeof getTranslations<"Credits">>>;
  whereLabel: (where: string[]) => string;
}) {
  return (
    <section aria-labelledby={id} className="flex flex-col gap-4">
      <h2 id={id} className="text-2xl font-bold">
        {title}
      </h2>
      <p className="max-w-prose text-muted">{intro}</p>
      <ul className={`flex flex-col divide-y divide-border ${card}`}>
        {items.map((e) => (
          <li key={e.id} className="flex flex-col gap-1 px-5 py-4 sm:flex-row sm:items-baseline sm:justify-between sm:gap-6">
            <div className="flex min-w-0 flex-col gap-0.5">
              <ExtLink href={e.homepage}>
                {e.name}
                {e.version !== "—" && <span className="font-normal text-muted"> {e.version}</span>}
              </ExtLink>
              <span className="text-sm text-muted">
                {e.partOf ? `${t("includedIn", { package: e.partOf })} · ` : ""}
                {whereLabel(e.where)}
                {e.source && (
                  <>
                    {" · "}
                    <ExtLink href={e.source}>{t("source")}</ExtLink>
                  </>
                )}
                {e.build && (
                  <>
                    {" · "}
                    <ExtLink href={e.build}>{t("build")}</ExtLink>
                  </>
                )}
              </span>
            </div>
            {"licenseUrl" in e && e.licenseUrl ? (
              <span className="shrink-0 text-sm font-medium">
                <ExtLink href={e.licenseUrl}>{e.license}</ExtLink>
              </span>
            ) : (
              <span className="shrink-0 text-sm font-medium">{e.license}</span>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}
